1	//! One client session: each message from stdin dispatched, each answer
2	//! written to stdout as one line under one lock, and the `list_changed`
3	//! check (road map 14's MC3, spec §11 MC-4).
4	//!
5	//! **What is answered here and what is forwarded.** `initialize` and `ping`
6	//! never touch the socket, so a client starts with no Frame Job running and a
7	//! `ping` is answered while a long call holds the app. `tools/list` is the
8	//! app's when it answers within `LIST_READ_TIMEOUT` and the bundle's
9	//! snapshot otherwise; it never launches anything (MC-4). `tools/call`
10	//! launches its own bundle when no socket answers. Anything else is
11	//! forwarded when the app answers and is `-32601` when it does not.
12	//!
13	//! **`list_changed`.** After a list from the snapshot, or a launch, the
14	//! next forwarded call is followed by a live `tools/list`; when its tools
15	//! differ from the ones this session was last given — as JSON VALUES, never
16	//! bytes, since the catalog's key order differs between processes (MC1's
17	//! B9) — the client is told `notifications/tools/list_changed`.
18	//!
19	//! **A launch that never answered** strands the session: its later calls
20	//! that find no socket answer the stranded sentence and launch nothing, so
21	//! an instance that started but never bound is not joined by another on
22	//! every call. The check and the launch are one critical section per
23	//! session, so concurrent calls that all found no socket launch at most
24	//! once between them.
25	
26	use std::io::Write;
27	use std::path::Path;
28	use std::sync::{Arc, Mutex};
29	
30	use serde_json::{json, Value};
31	
32	use crate::bundle;
33	use crate::launch::{self, Launched};
34	use crate::mcp_versions;
35	use crate::socket::{self, Reach};
36	
37	/// stdout, behind one lock: one message, one line, flushed.
38	pub struct Output {
39	    stdout: Mutex<std::io::Stdout>,
40	}
41	
42	impl Default for Output {
43	    fn default() -> Self {
44	        Self::new()
45	    }
46	}
47	
48	impl Output {
49	    pub fn new() -> Output {
50	        Output {
51	            stdout: Mutex::new(std::io::stdout()),
52	        }
53	    }
54	
55	    /// Writes `message` as compact JSON and a newline, then flushes.
56	    pub fn write(&self, message: &Value) {
57	        let mut line = message.to_string().into_bytes();
58	        line.push(b'\n');
59	        let stdout = self.stdout.lock().unwrap_or_else(|e| e.into_inner());
60	        let mut handle = stdout.lock();
61	        let _ = handle.write_all(&line).and_then(|()| handle.flush());
62	    }
63	}
64	
65	#[derive(Default)]
66	struct State {
67	    /// The tools this session's client was last given.
68	    last_given: Option<Value>,
69	    /// A live list is due after the next forwarded call.
70	    check_due: bool,
71	    /// The timeout sentence of this session's launch that never answered.
72	    stranded: Option<String>,
73	}
74	
75	/// A client session's state, behind one lock.
76	pub struct Session {
77	    state: Mutex<State>,
78	    /// Held from a call's `stranded` check through its launch, so a call
79	    /// that waited behind a launch that never answered sees `stranded`
80	    /// rather than launching a second instance.
81	    launching: Mutex<()>,
82	}
83	
84	impl Default for Session {
85	    fn default() -> Self {
86	        Self::new()
87	    }
88	}
89	
90	/// Reads one stdin line: a blank one is skipped; JSON that does not parse
91	/// is `-32700` and a batch `-32600`, each with a null id; a notification
92	/// (no `id`) or a response (no `method`) is dropped and never forwarded;
93	/// every other message is handled on a thread of its own.
94	pub fn dispatch(line: &[u8], session: &Arc<Session>, out: &Arc<Output>) {
95	    if line.iter().all(u8::is_ascii_whitespace) {
96	        return;
97	    }
98	    let message: Value = match serde_json::from_slice(line) {
99	        Ok(message) => message,
100	        Err(_) => return out.write(&error(Value::Null, -32700, "parse error")),
101	    };
102	    let Some(object) = message.as_object() else {
103	        let text = if message.is_array() {
104	            "batches are not supported"
105	        } else {
106	            "a message must be a JSON object"
107	        };
108	        return out.write(&error(Value::Null, -32600, text));
109	    };
110	    if !object.contains_key("id") || !object.contains_key("method") {
111	        return;
112	    }
113	    let (session, out) = (Arc::clone(session), Arc::clone(out));
114	    std::thread::spawn(move || session.handle(message, &out));
115	}
116	
117	impl Session {
118	    pub fn new() -> Session {
119	        Session {
120	            state: Mutex::new(State::default()),
121	            launching: Mutex::new(()),
122	        }
123	    }
124	
125	    fn state(&self) -> std::sync::MutexGuard<'_, State> {
126	        self.state.lock().unwrap_or_else(|e| e.into_inner())
127	    }
128	
129	    /// Answers one request (it has an `id` and a `method`).
130	    pub fn handle(&self, message: Value, out: &Output) {
131	        let id = message.get("id").cloned().unwrap_or(Value::Null);
132	        let Some(method) = message.get("method").and_then(Value::as_str) else {
133	            return out.write(&error(id, -32600, "the method must be a string"));
134	        };
135	        match method {
136	            "initialize" => out.write(&initialize(id, &message)),
137	            "ping" => out.write(&result(id, json!({}))),
138	            "tools/list" => out.write(&self.tools_list(id, &message)),
139	            "tools/call" => self.tools_call(id, &message, out),
140	            other => out.write(&forward_other(id, other, &message)),
141	        }
142	    }
143	
144	    fn tools_list(&self, id: Value, message: &Value) -> Value {
145	        let path = match socket::socket_path() {
146	            Ok(path) => path,
147	            Err(reason) => return self.snapshot_list(id, &reason),
148	        };
149	        let answers = socket::reach(&path) == Reach::Answers;
150	        let why = if !answers {
151	            format!("nothing answers at {}", path.display())
152	        } else {
153	            match socket::post(&path, message, Some(socket::LIST_READ_TIMEOUT)) {
154	                Ok(Some(answer)) => match answer.pointer("/result/tools") {
155	                    Some(tools) if tools.is_array() => {
156	                        let mut state = self.state();
157	                        state.last_given = Some(tools.clone());
158	                        state.check_due = false;
159	                        return answer;
160	                    }
161	                    _ => format!("Frame Job's tools/list at {} held no tools", path.display()),
162	                },
163	                Ok(None) => format!(
164	                    "Frame Job answered tools/list at {} with no body",
165	                    path.display()
166	                ),
167	                Err(reason) => reason,
168	            }
169	        };
170	        self.snapshot_list(id, &why)
171	    }
172	
173	    /// The snapshot's tools, or `-32603` naming the snapshot and `why` the
174	    /// app did not answer.
175	    fn snapshot_list(&self, id: Value, why: &str) -> Value {
176	        let snapshot = bundle::own_bundle().and_then(|bundle| bundle::read_snapshot(&bundle));
177	        match snapshot {
178	            Ok(snapshot) => {
179	                let mut state = self.state();
180	                state.last_given = Some(snapshot.tools.clone());
181	                state.check_due = true;
182	                result(id, json!({"tools": snapshot.tools}))
183	            }
184	            Err(reason) => error(
185	                id,
186	                -32603,
187	                &format!(
188	                    "no tools to list: {reason} ({}); and {why}",
189	                    bundle::SNAPSHOT_RELATIVE
190	                ),
191	            ),
192	        }
193	    }
194	
195	    fn tools_call(&self, id: Value, message: &Value, out: &Output) {
196	        let path = match socket::socket_path() {
197	            Ok(path) => path,
198	            Err(reason) => return out.write(&call_error(id, &reason)),
199	        };
200	        match socket::reach(&path) {
201	            Reach::Answers => {}
202	            Reach::Unreachable(reason) => return out.write(&call_error(id, &reason)),
203	            Reach::Absent => {
204	                let _launching = self.launching.lock().unwrap_or_else(|e| e.into_inner());
205	                if let Some(sentence) = self.state().stranded.clone() {
206	                    return out.write(&call_error(id, &sentence));
207	                }
208	                let bundle = match bundle::own_bundle() {
209	                    Ok(bundle) => bundle,
210	                    Err(reason) => return out.write(&call_error(id, &reason)),
211	                };
212	                match launch::ensure_running(&bundle, &path) {
213	                    Ok(Launched::Started) => self.state().check_due = true,
214	                    Ok(Launched::AlreadyUp) => {}
215	                    Err(reason) => {
216	                        if reason.starts_with(launch::TIMEOUT_OPENING) {
217	                            self.state().stranded = Some(stranded_sentence(&reason, &path));
218	                        }
219	                        eprintln!("framejob-mcp: {reason}");
220	                        return out.write(&call_error(id, &reason));
221	                    }
222	                }
223	            }
224	        }
225	        match socket::post(&path, message, None) {
226	            Ok(Some(answer)) => out.write(&answer),
227	            Ok(None) => {
228	                return out.write(&call_error(id, "Frame Job answered the call with no body"))
229	            }
230	            Err(reason) => return out.write(&call_error(id, &reason)),
231	        }
232	        self.check_list(&path, out);
233	    }
234	
235	    /// After a forwarded call: when a check is due, a live `tools/list`
236	    /// compared with the last-given tools as JSON values.
237	    fn check_list(&self, path: &Path, out: &Output) {
238	        if !self.state().check_due {
239	            return;
240	        }
241	        let ask =
242	            json!({"jsonrpc": "2.0", "id": "framejob-mcp-list-check", "method": "tools/list"});
243	        let live = match socket::post(path, &ask, None) {
244	            Ok(Some(answer)) => answer
245	                .pointer("/result/tools")
246	                .filter(|t| t.is_array())
247	                .cloned(),
248	            Ok(None) => None,
249	            Err(reason) => {
250	                eprintln!("framejob-mcp: the list check: {reason}");
251	                None
252	            }
253	        };
254	        let mut state = self.state();
255	        state.check_due = false;
256	        let Some(live) = live else { return };
257	        if state.last_given.as_ref() != Some(&live) {
258	            state.last_given = Some(live);
259	            out.write(&json!({"jsonrpc": "2.0", "method": "notifications/tools/list_changed"}));
260	        }
261	    }
262	}
