728	/// Reads and checks `<bundle>/Contents/Resources/agent-catalog.json`.
729	pub fn read_snapshot(bundle: &Path) -> Result<Snapshot, String> {
730	    let path = bundle.join(SNAPSHOT_RELATIVE);
731	    let shown = path.display();
732	    let bytes = std::fs::read(&path).map_err(|e| format!("could not read {shown}: {e}"))?;
733	    let mut value: Value =
734	        serde_json::from_slice(&bytes).map_err(|e| format!("{shown} is not JSON: {e}"))?;
735	    let version = value
736	        .get("version")
737	        .and_then(Value::as_str)
738	        .ok_or_else(|| format!("{shown} has no string `version`"))?
739	        .to_string();
740	    let tools = value
741	        .get_mut("tools")
742	        .filter(|tools| tools.is_array())
743	        .map(Value::take)
744	        .ok_or_else(|| format!("{shown} has no array `tools`"))?;
745	    Ok(Snapshot { version, tools })
746	}
