748	//! `framejob_mcp` — the stdio MCP server bundled as
749	//! `Frame Job.app/Contents/Helpers/framejob-mcp` (road map 14's MC3, spec §11
750	//! MC-3, MC-4, MC-6). An MCP client starts it; it speaks newline-delimited
751	//! JSON-RPC on stdin and stdout and reaches the running app over the agent
752	//! server's Unix socket. It answers `initialize` and `ping` itself, answers
753	//! `tools/list` from the app when one answers and from its bundle's catalog
754	//! snapshot when none does, and launches its own bundle in the background
755	//! on the first `tools/call` that finds no socket.
756	//!
757	//! stdout carries protocol only; anything else this process says goes to
758	//! stderr, each line starting `framejob-mcp: ` (never `Frame Job: `, the
759	//! parity check's prefix). The module map is `mcp-proxy/CLAUDE.md`.
760	
761	pub mod bundle;
762	pub mod launch;
763	#[path = "../../core/src/mcp_versions.rs"]
764	pub mod mcp_versions;
765	pub mod session;
766	pub mod socket;
767	
768	use std::io::BufRead;
769	use std::sync::Arc;
770	
771	/// The stdin loop: one `Session` and one `Output` for the process, each
772	/// line dispatched as it arrives (a request on its own thread, so a `ping`
773	/// is answered while a long call is held). At stdin's end the process exits
774	/// at once, without waiting for a call still in flight: the client that
775	/// would read its answer has gone.
776	pub fn run() -> ! {
777	    let session = Arc::new(session::Session::new());
778	    let out = Arc::new(session::Output::new());
779	    let stdin = std::io::stdin();
780	    let mut input = stdin.lock();
781	    let mut line = Vec::new();
782	    loop {
783	        line.clear();
784	        match input.read_until(b'\n', &mut line) {
785	            Ok(0) => break,
786	            Ok(_) => session::dispatch(&line, &session, &out),
787	            Err(error) => {
788	                eprintln!("framejob-mcp: stdin: {error}");
789	                break;
790	            }
791	        }
792	    }
793	    std::process::exit(0)
794	}
