324	//! The agent server's socket, from the proxy's side: where it is (spec §11
325	//! MC-1, MC-6), whether something answers there, and one HTTP/1.1 POST over
326	//! it. The app's server is `tiny_http` 0.12 (`core/src/agent.rs`), which
327	//! answers a body of 32 768 bytes or more CHUNKED, and a `tools/list` is
328	//! about 240 KB, so the reader decodes both `Content-Length` and chunked
329	//! bodies (and reads to the close when a response has neither).
330	
331	use std::io::{BufRead, BufReader, ErrorKind, Read, Write};
332	use std::os::unix::net::UnixStream;
333	use std::path::{Path, PathBuf};
334	use std::time::Duration;
335	
336	use serde_json::Value;
337	
338	/// Overrides the socket path, for the app and the proxy alike (MC-6).
339	pub const SOCKET_ENV: &str = "RC_AGENT_SOCKET";
340	
341	/// How long a forwarded `tools/list` may wait for the app before the
342	/// snapshot answers instead: the app serves one request at a time, so
343	/// another client's long call holds it.
344	pub const LIST_READ_TIMEOUT: Duration = Duration::from_secs(5);
345	
346	/// The largest response body the reader takes (the app's own request cap).
347	const MAX_BODY_BYTES: usize = 8 * 1024 * 1024;
348	
349	/// `RC_AGENT_SOCKET` when set and not empty, else
350	/// `$HOME/Library/Application Support/Frame Job/Agent/agent.sock` (MC-1).
351	pub fn socket_path() -> Result<PathBuf, String> {
352	    if let Some(path) = std::env::var_os(SOCKET_ENV).filter(|path| !path.is_empty()) {
353	        return Ok(PathBuf::from(path));
354	    }
355	    let home = std::env::var_os("HOME")
356	        .filter(|home| !home.is_empty())
357	        .ok_or_else(|| "HOME is not set, so the agent socket's path is unknown".to_string())?;
358	    Ok(PathBuf::from(home).join("Library/Application Support/Frame Job/Agent/agent.sock"))
359	}
360	
361	/// True when `RC_AGENT_SOCKET` is set and not empty: a scratch instance,
362	/// which a launch tells where to bind (MC-6).
363	pub fn is_scratch() -> bool {
364	    std::env::var_os(SOCKET_ENV).is_some_and(|path| !path.is_empty())
365	}
366	
367	/// What a connect to the socket found.
368	#[derive(Debug, Clone, PartialEq, Eq)]
369	pub enum Reach {
370	    /// Something accepted the connection.
371	    Answers,
372	    /// No file at the path, or a file nothing listens on (a quit's or a
373	    /// crash's leftover): Frame Job is not running there.
374	    Absent,
375	    /// Anything else, in a sentence.
376	    Unreachable(String),
377	}
378	
379	/// Connects to `path` and closes at once.
380	pub fn reach(path: &Path) -> Reach {
381	    match UnixStream::connect(path) {
382	        Ok(_) => Reach::Answers,
383	        Err(error)
384	            if matches!(
385	                error.kind(),
386	                ErrorKind::NotFound | ErrorKind::ConnectionRefused
387	            ) =>
388	        {
389	            Reach::Absent
390	        }
391	        Err(error) => Reach::Unreachable(format!(
392	            "could not connect to Frame Job at {}: {error}",
393	            path.display()
394	        )),
395	    }
396	}
397	
398	/// POSTs `message` to `/mcp` over the socket and reads the answer: 200 →
399	/// its body as JSON, 202 → None (a notification's answer), anything else →
400	/// an error naming the status. `read_timeout` bounds each read (None waits
401	/// as long as the app takes); a read that times out is an error.
402	pub fn post(
403	    path: &Path,
404	    message: &Value,
405	    read_timeout: Option<Duration>,
406	) -> Result<Option<Value>, String> {
407	    let shown = path.display();
408	    let mut stream = UnixStream::connect(path)
409	        .map_err(|e| format!("could not connect to Frame Job at {shown}: {e}"))?;
410	    stream
411	        .set_read_timeout(read_timeout)
412	        .map_err(|e| format!("could not set a read timeout on {shown}: {e}"))?;
413	    let body = serde_json::to_vec(message).map_err(|e| format!("could not encode: {e}"))?;
414	    let head = format!(
415	        "POST /mcp HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\n\
416	         Accept: application/json, text/event-stream\r\nContent-Length: {}\r\n\
417	         Connection: close\r\n\r\n",
418	        body.len()
419	    );
420	    stream
421	        .write_all(head.as_bytes())
422	        .and_then(|()| stream.write_all(&body))
423	        .and_then(|()| stream.flush())
424	        .map_err(|e| format!("could not write to Frame Job at {shown}: {e}"))?;
425	    let mut reader = BufReader::new(stream);
426	    let (status, body) = read_response(&mut reader).map_err(|e| match e.kind() {
427	        ErrorKind::WouldBlock | ErrorKind::TimedOut => format!(
428	            "Frame Job did not answer at {shown} within {} s",
429	            read_timeout.map_or(0, |t| t.as_secs())
430	        ),
431	        _ => format!("could not read Frame Job's answer at {shown}: {e}"),
432	    })?;
433	    match status {
434	        200 => serde_json::from_slice(&body)
435	            .map(Some)
436	            .map_err(|e| format!("Frame Job's answer at {shown} is not JSON: {e}")),
437	        202 => Ok(None),
438	        code => Err(format!("Frame Job answered HTTP {code}")),
439	    }
440	}
441	
442	fn invalid(what: &str) -> std::io::Error {
443	    std::io::Error::new(ErrorKind::InvalidData, what.to_string())
444	}
445	
446	/// One header or chunk-size line, without its CRLF; EOF is an error.
447	fn read_line(reader: &mut impl BufRead) -> std::io::Result<String> {
448	    let mut line = Vec::new();
449	    if reader.read_until(b'\n', &mut line)? == 0 {
450	        return Err(invalid("the connection closed mid-response"));
451	    }
452	    while matches!(line.last(), Some(b'\n' | b'\r')) {
453	        line.pop();
454	    }
455	    String::from_utf8(line).map_err(|_| invalid("a response line is not UTF-8"))
456	}
457	
458	/// The status code and the decoded body of one HTTP/1.1 response.
459	fn read_response(reader: &mut impl BufRead) -> std::io::Result<(u16, Vec<u8>)> {
460	    let status_line = read_line(reader)?;
461	    let status = status_line
462	        .split_whitespace()
463	        .nth(1)
464	        .and_then(|code| code.parse::<u16>().ok())
465	        .ok_or_else(|| invalid("the status line has no code"))?;
466	    let mut length = None;
467	    let mut chunked = false;
468	    loop {
469	        let line = read_line(reader)?;
470	        if line.is_empty() {
471	            break;
472	        }
473	        let Some((name, value)) = line.split_once(':') else {
474	            continue;
475	        };
476	        let (name, value) = (name.trim(), value.trim());
477	        if name.eq_ignore_ascii_case("content-length") {
478	            length = Some(
479	                value
480	                    .parse::<usize>()
481	                    .map_err(|_| invalid("a bad Content-Length"))?,
482	            );
483	        } else if name.eq_ignore_ascii_case("transfer-encoding") {
484	            chunked = value.to_ascii_lowercase().contains("chunked");
485	        }
486	    }
487	    let body = if chunked {
488	        read_chunked(reader)?
489	    } else if let Some(length) = length {
490	        if length > MAX_BODY_BYTES {
491	            return Err(invalid("the answer is over 8 MiB"));
492	        }
493	        let mut body = vec![0; length];
494	        reader.read_exact(&mut body)?;
495	        body
496	    } else {
497	        let mut body = Vec::new();
498	        reader
499	            .take(MAX_BODY_BYTES as u64 + 1)
500	            .read_to_end(&mut body)?;
501	        body
502	    };
503	    if body.len() > MAX_BODY_BYTES {
504	        return Err(invalid("the answer is over 8 MiB"));
505	    }
506	    Ok((status, body))
507	}
508	
509	/// A chunked body: hex sizes (extensions ignored), each chunk and its CRLF,
510	/// then the zero chunk and any trailer lines up to the blank one.
511	fn read_chunked(reader: &mut impl BufRead) -> std::io::Result<Vec<u8>> {
512	    let mut body = Vec::new();
513	    loop {
514	        let line = read_line(reader)?;
515	        let size = line.split(';').next().unwrap_or("").trim();
516	        let size = usize::from_str_radix(size, 16).map_err(|_| invalid("a bad chunk size"))?;
517	        if size == 0 {
518	            while !read_line(reader)?.is_empty() {}
519	            return Ok(body);
520	        }
521	        if body
522	            .len()
523	            .checked_add(size)
524	            .is_none_or(|end| end > MAX_BODY_BYTES)
525	        {
526	            return Err(invalid("the answer is over 8 MiB"));
527	        }
528	        let start = body.len();
529	        body.resize(start + size, 0);
530	        reader.read_exact(&mut body[start..])?;
531	        let mut crlf = [0u8; 2];
532	        reader.read_exact(&mut crlf)?;
533	        if &crlf != b"\r\n" {
534	            return Err(invalid("a chunk does not end in CRLF"));
535	        }
536	    }
537	}
538	//! Launching Frame Job for a `tools/call` that found no socket (spec §11
539	//! MC-4): its own bundle, in the background (`open -n -g`), at most one
540	//! instance between all the proxies that find no socket at once.
541	//!
542	//! **The lock.** `agent.launch.lock` beside the socket, taken with
543	//! `File::lock` (exclusive, blocking) before the re-check and **held until
544	//! the poll ends**: released before the poll, a second proxy's re-check
545	//! would find nothing answering yet and launch a second instance. A proxy
546	//! that waited on the lock re-checks and finds the first one's instance.
547	//!
548	//! **A scratch socket** (`RC_AGENT_SOCKET` set, MC-6) is passed to the
549	//! instance with `open --env`, with `-ApplePersistenceIgnoreState YES` and
550	//! its stderr written to `framejob-launch.log` beside the socket; the
551	//! person's own socket gets none of these, so their Frame Job opens as theirs.
552	
553	use std::ffi::OsString;
554	use std::fs::{DirBuilder, OpenOptions};
555	use std::os::unix::fs::{DirBuilderExt, OpenOptionsExt};
556	use std::path::Path;
557	use std::process::Command;
558	use std::time::{Duration, Instant};
559	
560	use crate::socket::{self, Reach};
561	
562	/// Overrides the wait for a launched instance, in whole seconds.
563	pub const WAIT_ENV: &str = "RC_MCP_LAUNCH_WAIT";
564	/// MC1's wait: a cold launch measured about a second.
565	pub const DEFAULT_WAIT_SECS: u64 = 60;
566	/// The launch lock's name, beside the socket.
567	pub const LOCK_NAME: &str = "agent.launch.lock";
568	/// A scratch launch's stderr, beside the socket.
569	pub const LAUNCH_LOG_NAME: &str = "framejob-launch.log";
570	/// How every timeout sentence begins (`Session` recognises one by it).
571	pub const TIMEOUT_OPENING: &str = "Frame Job did not answer at ";
572	/// How often the wait asks the socket.
573	const POLL: Duration = Duration::from_millis(50);
574	
575	/// A positive whole number of seconds in `RC_MCP_LAUNCH_WAIT`, else 60 s.
576	pub fn launch_wait() -> Duration {
577	    let seconds = std::env::var(WAIT_ENV)
578	        .ok()
579	        .and_then(|value| value.trim().parse::<u64>().ok())
580	        .filter(|seconds| *seconds > 0)
581	        .unwrap_or(DEFAULT_WAIT_SECS);
582	    Duration::from_secs(seconds)
583	}
584	
585	/// The `/usr/bin/open` arguments that launch `bundle` for `socket`. Pure.
586	pub fn open_arguments(bundle: &Path, socket: &Path, scratch: bool) -> Vec<OsString> {
587	    let mut arguments: Vec<OsString> = vec!["-n".into(), "-g".into()];
588	    if scratch {
589	        let mut env = OsString::from(format!("{}=", socket::SOCKET_ENV));
590	        env.push(socket.as_os_str());
591	        let folder = socket.parent().unwrap_or(Path::new("/"));
592	        arguments.push("--env".into());
593	        arguments.push(env);
594	        arguments.push("--stderr".into());
595	        arguments.push(folder.join(LAUNCH_LOG_NAME).into_os_string());
596	    }
597	    arguments.push(bundle.as_os_str().to_os_string());
598	    if scratch {
599	        arguments.push("--args".into());
600	        arguments.push("-ApplePersistenceIgnoreState".into());
601	        arguments.push("YES".into());
602	    }
603	    arguments
604	}
605	
606	/// The sentence a launch that never bound answers.
607	pub fn timeout_sentence(socket: &Path, wait: Duration, bundle: &Path) -> String {
608	    format!(
609	        "{TIMEOUT_OPENING}{} within {} s of launching {}",
610	        socket.display(),
611	        wait.as_secs(),
612	        bundle.display()
613	    )
614	}
615	
616	/// Whether the socket answered at once or after a launch.
617	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
618	pub enum Launched {
619	    AlreadyUp,
620	    Started,
621	}
622	
623	/// Makes sure something answers at `socket`, launching `bundle` if
624	/// nothing does once the lock is held. The error is a sentence; a launch
625	/// that never answered is `timeout_sentence`'s.
626	pub fn ensure_running(bundle: &Path, socket: &Path) -> Result<Launched, String> {
627	    let folder = socket
628	        .parent()
629	        .ok_or_else(|| format!("the socket path {} has no folder", socket.display()))?;
630	    if !folder.exists() {
631	        DirBuilder::new()
632	            .recursive(true)
633	            .mode(0o700)
634	            .create(folder)
635	            .map_err(|e| format!("could not make {}: {e}", folder.display()))?;
636	    }
637	    let lock_path = folder.join(LOCK_NAME);
638	    let lock = OpenOptions::new()
639	        .read(true)
640	        .write(true)
641	        .create(true)
642	        .truncate(false)
643	        .mode(0o600)
644	        .open(&lock_path)
645	        .map_err(|e| format!("could not open {}: {e}", lock_path.display()))?;
646	    lock.lock()
647	        .map_err(|e| format!("could not lock {}: {e}", lock_path.display()))?;
648	    match socket::reach(socket) {
649	        Reach::Answers => return Ok(Launched::AlreadyUp),
650	        Reach::Unreachable(reason) => return Err(reason),
651	        Reach::Absent => {}
652	    }
653	    let arguments = open_arguments(bundle, socket, socket::is_scratch());
654	    let opened = Command::new("/usr/bin/open")
655	        .args(&arguments)
656	        .output()
657	        .map_err(|e| format!("could not run /usr/bin/open: {e}"))?;
658	    if !opened.status.success() {
659	        return Err(format!(
660	            "/usr/bin/open {} failed ({}): {}",
661	            bundle.display(),
662	            opened.status,
663	            String::from_utf8_lossy(&opened.stderr).trim()
664	        ));
665	    }
666	    let wait = launch_wait();
667	    let started = Instant::now();
668	    loop {
669	        if socket::reach(socket) == Reach::Answers {
670	            drop(lock);
671	            return Ok(Launched::Started);
672	        }
673	        if started.elapsed() >= wait {
674	            drop(lock);
675	            return Err(timeout_sentence(socket, wait, bundle));
676	        }
677	        std::thread::sleep(POLL);
678	    }
679	}
680	//! The bundle this proxy lives in, and the catalog snapshot the build wrote
681	//! into it (road map 14's MC1 q1: `-RCWriteCatalog` in the "Write Agent
682	//! Catalog" build phase). A proxy launches only its OWN bundle (MC-4), so a
683	//! copy of Frame Job launches itself and never another copy.
684	
685	use std::path::{Path, PathBuf};
686	
687	use serde_json::Value;
688	
689	/// Where the build puts the snapshot, relative to the bundle.
690	pub const SNAPSHOT_RELATIVE: &str = "Contents/Resources/agent-catalog.json";
691	
692	/// `{version, tools}`: the bundle's short version and its `tools/list`
693	/// catalog as the app would answer it.
694	#[derive(Debug, Clone, PartialEq)]
695	pub struct Snapshot {
696	    pub version: String,
697	    pub tools: Value,
698	}
699	
700	/// The `.app` that holds this executable as `Contents/Helpers/<name>`,
701	/// symlinks resolved; anything else is an error naming the executable.
702	pub fn own_bundle() -> Result<PathBuf, String> {
703	    let exe = std::env::current_exe()
704	        .map_err(|e| format!("framejob-mcp cannot find its own executable: {e}"))?;
705	    let exe = exe
706	        .canonicalize()
707	        .map_err(|e| format!("framejob-mcp cannot resolve {}: {e}", exe.display()))?;
708	    let outside = || {
709	        format!(
710	            "framejob-mcp is not inside a Frame Job bundle: {} is not <X>.app/Contents/Helpers/<name>, \
711	             so there is no Frame Job to launch",
712	            exe.display()
713	        )
714	    };
715	    let helpers = exe.parent().ok_or_else(outside)?;
716	    let contents = helpers.parent().ok_or_else(outside)?;
