//! Embedded MCP server: the streamable-HTTP transport and JSON-RPC layer
//! for the app's agent integration (tools only — no resources, prompts,
//! or server-initiated streams). The protocol lives here; executing a tool
//! is delegated to the host application through the handler installed at
//! start, so this module stays generic: it knows the catalog it was given
//! and nothing about documents.
//!
//! Transport notes: one listener, [`start_socket`], binds a Unix socket at
//! a path (road map 14, spec §11 MC-1), chmod 0600, never unlinking a file
//! already there; road map 14's MC4 deleted the TCP one. It answers every
//! JSON-RPC POST with a single `application/json` response (the
//! streamable-HTTP spec allows this in place of an SSE stream). Stateless — no session IDs are
//! issued, and GET/DELETE report 405 as the spec directs for servers
//! without server-push or client-terminated sessions.
//!
//! **A socket listener never lets `tiny_http`'s `Drop` run against a file
//! that is no longer its own** (road map 14's MC1, S7): 0.12's `Server`
//! drop connects to its path and unlinks it unconditionally, so a listener
//! whose file was unlinked and re-bound by another instance would delete
//! that instance's socket. The listener records the file's device and inode
//! when it binds ([`SocketClaim`]); [`AgentServer::shutdown`] lets the drop
//! run only while the file is still that one, and [`AgentServer::release`]
//! unlinks it only then and abandons the listener without a join.

use std::io::Read;
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::thread::JoinHandle;

use serde_json::{json, Value};

/// Executes one tool call: (tool name, arguments JSON) -> CallToolResult
/// JSON (`{"content": [...], "isError": bool}`). None means the handler
/// itself failed (as opposed to the tool reporting an error result).
pub type ToolHandler = Box<dyn Fn(&str, &str) -> Option<String> + Send + Sync>;

pub struct AgentConfig {
    pub name: String,
    pub version: String,
    /// The `tools/list` catalog, pre-validated to be a JSON array.
    pub tools: Value,
    pub handler: ToolHandler,
}

/// macOS's `sun_path` holds 104 bytes with the terminating NUL, so a socket
/// path may be 103 bytes long (MC1's S1: 103 binds, 104 does not).
pub const MAX_SOCKET_PATH_BYTES: usize = 103;

/// The socket file a listener bound, by the device and inode `lstat` read
/// straight after the bind: what "still this listener's file" means.
pub struct SocketClaim {
    path: PathBuf,
    dev: u64,
    ino: u64,
}

impl SocketClaim {
    /// True while `lstat(path)` answers the device and inode the bind left
    /// there. A file unlinked, or replaced by another listener's, is not.
    pub fn is_current(&self) -> bool {
        std::fs::symlink_metadata(&self.path)
            .map(|meta| meta.dev() == self.dev && meta.ino() == self.ino)
            .unwrap_or(false)
    }
}

pub struct AgentServer {
    server: Arc<tiny_http::Server>,
    thread: Option<JoinHandle<()>>,
    /// The socket file this listener bound.
    claim: Option<SocketClaim>,
}

impl AgentServer {
    /// Unblocks the accept loop and joins the serving thread. A socket
    /// listener whose file is no longer its own is then forgotten rather
    /// than dropped, so `tiny_http`'s `Drop` neither connects to nor unlinks
    /// another listener's socket (S7); otherwise it drops, which unlinks its
    /// own file.
    pub fn shutdown(mut self) {
        self.server.unblock();
        if let Some(thread) = self.thread.take() {
            let _ = thread.join();
        }
        if self.claim.as_ref().is_some_and(|claim| !claim.is_current()) {
            std::mem::forget(self.server);
        }
    }

    /// For quit: unlinks the socket file only if it is still the one this
    /// listener bound, then abandons the listener. Its thread is neither
    /// unblocked nor joined and nothing is dropped, so a call in flight
    /// cannot hold the caller; process exit ends the thread.
    pub fn release(self) {
        if let Some(claim) = &self.claim {
            if claim.is_current() {
                let _ = std::fs::remove_file(&claim.path);
            }
        }
        std::mem::forget(self);
    }
}

const MAX_BODY_BYTES: usize = 8 * 1024 * 1024;

/// Binds the server on a Unix socket at `path`, chmod 0600, and returns the
/// running server with its claim on the file. A relative path and one over
/// [`MAX_SOCKET_PATH_BYTES`] are refused by name. An existing file is never
/// unlinked first: `tiny_http` refuses to bind over one (S4–S6), and whether
/// a file at the path is a crash's leftover is the host's to decide (MC-2).
pub fn start_socket(path: &Path, config: AgentConfig) -> Result<AgentServer, String> {
    if !config.tools.is_array() {
        return Err("tools catalog must be a JSON array".to_string());
    }
    let shown = path.display();
    if !path.is_absolute() {
        return Err(format!("socket path must be absolute: {shown}"));
    }
    let n = path.as_os_str().len();
    if n > MAX_SOCKET_PATH_BYTES {
        return Err(format!(
            "socket path is {n} bytes; macOS allows {MAX_SOCKET_PATH_BYTES}: {shown}"
        ));
    }
    let server =
        tiny_http::Server::http_unix(path).map_err(|e| format!("could not bind {shown}: {e}"))?;
    // A fresh bind's file takes the umask (0755 under 022, S3). On failure
    // the server drops here, which unlinks the file this call just made.
    std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600))
        .map_err(|e| format!("could not make {shown} 0600: {e}"))?;
    let meta = match std::fs::symlink_metadata(path) {
        Ok(meta) => meta,
        Err(e) => {
            // Whatever is at the path now may not be this bind's file, so
            // the drop must not unlink it (S7).
            std::mem::forget(server);
            return Err(format!("could not read {shown}: {e}"));
        }
    };
    let claim = SocketClaim {
        path: path.to_path_buf(),
        dev: meta.dev(),
        ino: meta.ino(),
    };
    let server = Arc::new(server);
    let accept = Arc::clone(&server);
    let thread = std::thread::spawn(move || serve(accept, config));
    Ok(AgentServer {
        server,
        thread: Some(thread),
        claim: Some(claim),
    })
}

enum Reply {
    Json(u16, Value),
    Empty(u16),
}

fn serve(server: Arc<tiny_http::Server>, config: AgentConfig) {
    for mut request in server.incoming_requests() {
        // One request at a time: tool calls serialize through the host's
        // main thread anyway, and a panic must not take the loop down.
        let reply = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            handle_request(&mut request, &config)
        }))
        .unwrap_or_else(|_| Reply::Json(500, rpc_error(Value::Null, -32603, "internal error")));
        let _ = match reply {
            Reply::Json(status, body) => request.respond(
                tiny_http::Response::from_string(body.to_string())
                    .with_status_code(status)
                    .with_header(
                        tiny_http::Header::from_bytes(
                            &b"Content-Type"[..],
                            &b"application/json"[..],
                        )
                        .expect("static header"),
                    ),
            ),
            Reply::Empty(status) => {
                request.respond(tiny_http::Response::empty(tiny_http::StatusCode(status)))
            }
        };
    }
}

fn handle_request(request: &mut tiny_http::Request, config: &AgentConfig) -> Reply {
    match request.method() {
        tiny_http::Method::Post => {}
        // No server-initiated SSE stream (GET) and no sessions to delete.
        _ => return Reply::Empty(405),
    }
    if request
        .body_length()
        .is_some_and(|len| len > MAX_BODY_BYTES)
    {
        return Reply::Empty(413);
    }
    let mut body = Vec::new();
    let mut reader = request.as_reader().take(MAX_BODY_BYTES as u64 + 1);
    if reader.read_to_end(&mut body).is_err() || body.len() > MAX_BODY_BYTES {
        return Reply::Empty(413);
    }
    let parsed: Value = match serde_json::from_slice(&body) {
        Ok(v) => v,
        Err(_) => return Reply::Json(400, rpc_error(Value::Null, -32700, "parse error")),
    };
    // A batch (2025-03-26 revision) is answered element-wise; notifications
    // produce no entry. All-notification input gets the bodiless 202.
    let replies: Vec<Value> = match parsed {
        Value::Array(items) => items
            .into_iter()
            .filter_map(|m| handle_message(m, config))
            .collect(),
        single => match handle_message(single, config) {
            Some(reply) => return Reply::Json(200, reply),
            None => return Reply::Empty(202),
        },
    };
    if replies.is_empty() {
        Reply::Empty(202)
    } else {
        Reply::Json(200, Value::Array(replies))
    }
}

/// Answers one JSON-RPC message; None for notifications (nothing to say).
fn handle_message(message: Value, config: &AgentConfig) -> Option<Value> {
    let Some(method) = message.get("method").and_then(Value::as_str) else {
        // A response to a server request — we never send any, so ignore.
        return None;
    };
    let id = message.get("id").cloned();
    let params = message.get("params").cloned().unwrap_or(json!({}));
    let Some(id) = id else {
        return None; // notification: nothing is ever returned
    };

    let reply = match method {
        "initialize" => {
            let requested = params
                .get("protocolVersion")
                .and_then(Value::as_str)
                .unwrap_or("");
            let version = crate::mcp_versions::negotiate(requested);
            rpc_result(
                id,
                json!({
                    "protocolVersion": version,
                    "capabilities": {"tools": {}},
                    "serverInfo": {"name": config.name, "version": config.version},
                }),
            )
        }
        "ping" => rpc_result(id, json!({})),
        "tools/list" => rpc_result(id, json!({"tools": config.tools})),
        "tools/call" => {
            let Some(name) = params.get("name").and_then(Value::as_str) else {
                return Some(rpc_error(id, -32602, "tools/call requires a tool name"));
            };
            let arguments = params.get("arguments").cloned().unwrap_or(json!({}));
            let arguments = arguments.to_string();
            match (config.handler)(name, &arguments) {
                None => rpc_error(id, -32603, "tool handler failed"),
                Some(result) => match serde_json::from_str::<Value>(&result) {
                    Ok(value) if value.is_object() => rpc_result(id, value),
                    _ => rpc_error(id, -32603, "tool returned invalid JSON"),
                },
            }
        }
        _ => rpc_error(id, -32601, &format!("method not found: {method}")),
    };
    Some(reply)
}

fn rpc_result(id: Value, result: Value) -> Value {
    json!({"jsonrpc": "2.0", "id": id, "result": result})
}

fn rpc_error(id: Value, code: i64, message: &str) -> Value {
    json!({"jsonrpc": "2.0", "id": id, "error": {"code": code, "message": message}})
}
//! C FFI for the embedded MCP agent server (`rc_agent_*` in the header).
//!
//! One listener per process, in one slot: the Unix socket
//! (`rc_agent_socket_start` / `_release`, `SOCKET`, road map 14; MC4
//! deleted the TCP server and its slot). A second start is refused. It is
//! built from an [`AgentConfig`] (`host_config`), one catalog through one
//! handler. The host's tool handler is a C function pointer invoked from
//! the server thread; its return value must come from
//! [`rc_agent_string_create`] so this side can reclaim the allocation.

use std::ffi::{c_char, c_void, CStr, CString};
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::path::Path;
use std::ptr;
use std::sync::Mutex;

use crate::agent::{self, AgentConfig, AgentServer};
use crate::ffi_util::{fallible_op, read_cstr};

/// C signature of the host tool handler. See the header for the contract.
pub type RcAgentToolHandler = unsafe extern "C" fn(
    context: *mut c_void,
    tool_name: *const c_char,
    arguments_json: *const c_char,
) -> *mut c_char;

/// The handler pointer and its context, made Send+Sync so a worker
/// thread may call them. The host guarantees the pair stays valid and
/// callable from any thread for the life of the server it was
/// registered with.
pub(crate) struct HostHandler {
    pub(crate) handler: RcAgentToolHandler,
    pub(crate) context: *mut c_void,
}
unsafe impl Send for HostHandler {}
unsafe impl Sync for HostHandler {}

impl HostHandler {
    pub(crate) fn call(&self, name: &str, arguments: &str) -> Option<String> {
        let name = CString::new(name.replace('\0', " ")).ok()?;
        let arguments = CString::new(arguments.replace('\0', " ")).ok()?;
        let raw = unsafe { (self.handler)(self.context, name.as_ptr(), arguments.as_ptr()) };
        if raw.is_null() {
            return None;
        }
        // Reclaims the rc_agent_string_create allocation.
        let owned = unsafe { CString::from_raw(raw) };
        owned.into_string().ok()
    }
}

static SOCKET: Mutex<Option<AgentServer>> = Mutex::new(None);

/// Reads the three strings the start takes and builds the
/// [`AgentConfig`] around the host's handler: the one place the catalog is
/// parsed and the handler wrapped.
///
/// # Safety
/// String arguments must be NULL or valid NUL-terminated C strings.
unsafe fn host_config(
    server_name: *const c_char,
    server_version: *const c_char,
    tools_json: *const c_char,
    handler: RcAgentToolHandler,
    context: *mut c_void,
) -> Result<AgentConfig, String> {
    let name = unsafe { read_cstr(server_name, "server_name") }?;
    let version = unsafe { read_cstr(server_version, "server_version") }?;
    let tools_text = unsafe { read_cstr(tools_json, "tools_json") }?;
    let tools: serde_json::Value = serde_json::from_str(&tools_text)
        .map_err(|e| format!("tools_json is not valid JSON: {e}"))?;
    let host = HostHandler { handler, context };
    Ok(AgentConfig {
        name,
        version,
        tools,
        handler: Box::new(move |tool, arguments| host.call(tool, arguments)),
    })
}

/// Allocates a NUL-terminated copy of `s` owned by this library, for tool
/// handlers to return. Never freed by the caller: ownership passes back
/// across the handler return.
///
/// # Safety
/// `s` must be NULL or a valid NUL-terminated C string.
#[no_mangle]
pub unsafe extern "C" fn rc_agent_string_create(s: *const c_char) -> *mut c_char {
    if s.is_null() {
        return ptr::null_mut();
    }
    let bytes = unsafe { CStr::from_ptr(s) }.to_bytes().to_vec();
    match CString::new(bytes) {
        Ok(owned) => owned.into_raw(),
        Err(_) => ptr::null_mut(),
    }
}

/// Binds the embedded MCP server's Unix-socket listener at `socket_path`,
/// chmod 0600. `tools_json` must be the `tools/list` catalog as a JSON
/// array; `handler` is called from the server thread for every
/// `tools/call` and must return a CallToolResult JSON object allocated
/// with [`rc_agent_string_create`], or NULL for handler failure. True, or false with a message through
/// `err_out`. One per process: a second start is an error ("agent socket
/// already bound"). Never unlinks an existing file.
///
/// # Safety
/// String arguments must be valid NUL-terminated C strings; `err_out`
/// must be NULL or a valid pointer to writable `*mut c_char`; `handler`
/// and `context` must remain valid and callable from any thread for the
/// life of the process, because [`rc_agent_socket_release`] never joins.
#[no_mangle]
pub unsafe extern "C" fn rc_agent_socket_start(
    socket_path: *const c_char,
    server_name: *const c_char,
    server_version: *const c_char,
    tools_json: *const c_char,
    handler: RcAgentToolHandler,
    context: *mut c_void,
    err_out: *mut *mut c_char,
) -> bool {
    let body = || {
        let path = unsafe { read_cstr(socket_path, "socket_path") }?;
        let config =
            unsafe { host_config(server_name, server_version, tools_json, handler, context) }?;

        let mut slot = SOCKET
            .lock()
            .map_err(|_| "socket lock poisoned".to_string())?;
        if slot.is_some() {
            return Err("agent socket already bound".to_string());
        }
        let server = agent::start_socket(Path::new(&path), config)?;
        *slot = Some(server);
        Ok(())
    };
    unsafe {
        fallible_op(
            err_out,
            "panic while binding agent socket",
            false,
            body,
            |()| true,
        )
    }
}

/// For quit. Takes the listener out of its slot and unlinks the socket
/// file only if it is still the one this listener bound (same device and
/// inode), then abandons the listener: its thread is neither unblocked nor
/// joined, so a call in flight cannot hold the quit, and process exit ends
/// it. `handler` and `context` must stay valid for the life of the process.
/// Safe when none is bound.
#[no_mangle]
pub extern "C" fn rc_agent_socket_release() {
    let server = catch_unwind(|| SOCKET.lock().ok().and_then(|mut slot| slot.take()));
    if let Ok(Some(server)) = server {
        let _ = catch_unwind(AssertUnwindSafe(|| server.release()));
    }
}

import Foundation

// MARK: - The argument gate: a call's keys against the tool's published schema

/// One comparison at dispatch, for all one hundred and four tools: the keys a
/// caller wrote against the properties the tool PUBLISHED, and every
/// stranger refused by name before a handler reads a thing
/// (kpgalligan/framejob#21; the measurement behind it is
/// `archive/roadmap-7.md` §11).
///
/// **The defect it closes.** No handler enumerates a caller's keys. Each
/// reads the names it knows out of the dictionary and builds a fresh op, so
/// a key nothing reads collides with nothing: a misspelt OPTIONAL argument
/// was dropped in silence and the edit applied without it, an argument no
/// op takes was ignored, and a misspelt REQUIRED argument was reported as
/// the right name missing rather than as the wrong one written. The core's
/// decoder would refuse every one of them by name (`Op` is
/// `deny_unknown_fields`) and never got the chance, because an op ARGUMENT
/// never reaches it — the app rebuilds the op first.
///
/// **Why a gate and not a forward.** Handing a caller's op to the core
/// unread would buy the same refusal and give up twenty-one the app makes on
/// its own account, six app-state defaults, eleven per-op transforms and one
/// correctness guard (§11.2). The gate keeps every one of them: it runs
/// before the handler and reads nothing but names.
///
/// **What it reads.** The catalog string `prepareCatalog()` built at launch
/// (spec §11 AI-3) — the same bytes `start()` registers with the server and a
/// caller sees over `tools/list` — parsed once into
/// each tool's property names. The startup parity check's five parts already
/// say that catalog is exactly the dispatch table, that every op tool prints
/// the core's own arguments and that `project` and `scope` are on the tools
/// they belong to (`AgentServer+Parity.swift`), so the set compared against
/// here is the one those five vouch for. It is state for
/// `proseWithoutArgument`'s reason: written once, by `prepareCatalog()` from
/// `main.swift` at launch, before any other thread exists, and only read
/// after — on the main thread and, for the `offMainTools`, on the lane's
/// caller's thread, which is safe because nothing writes it again.
///
/// **What it speaks.** The APP's sentence — the tool, the strangers and the
/// whole of what the tool does take — rather than the core's serde wording:
/// thirty-six tools have no core sentence to borrow, and `AgentIdScope.noSuchId`
/// set the house style ("No clip has id 17. get_project lists the clips.").
///
/// **What it cannot see.** A DECLARED argument no handler reads: the name
/// passes here and the handler ignores it, which is the class only a row
/// calling the running tool can catch — the optional half of section 3 in
/// `tools/proof/op_argument_proof.py`, which reads what the op DID. And a
/// value of the wrong TYPE under the right name, which is the argument
/// vocabulary's (`AgentServer+Arguments.swift`), one reader at a time.
///
/// A file of its own because `AgentServer.swift` is frozen at wiring
/// (app/CLAUDE.md) and this is neither a reader nor a startup check.
extension AgentServer {

    /// Every tool's published property names, keyed by tool, from the
    /// catalog `prepareCatalog()` built.
    private(set) static var publishedArguments: [String: Set<String>] = [:]

    /// Reads `catalog` — the string `catalogJSON()` answered, which
